enum RobotState { IDLE, DRIVE, AVOID };
RobotState currentState = DRIVE;

void setup() {
  Serial.begin(9600);
  switch (currentState) {
    case IDLE:  Serial.println("Waiting"); break;
    case DRIVE: Serial.println("Driving"); break;
    case AVOID: Serial.println("Avoiding obstacle"); break;
  }
}
void loop() {}

